#!/usr/bin/env node
// overruled: find the code that quietly overrules your policy page.
//   overruled sites <policy.md> [dir]
//       every line under dir that restates a number from the policy
//   overruled sites <policy.md> [dir] --from <old-policy.md | REV:path>
//       only numbers that changed, searched by their OLD value
//   flags: --json  --source-only  --residual (exit 1 if any in-source line remains)  --exclude <path>
//   overruled check [--config overruled.config.json] [--from REV] [--recorded run.ndjson --recorded-verdict v.json --recorded-pack p.evidence]
//                   [--max-attempts 3] [--kane-green] [--packet-only] [--no-commit]
//       the loop: Kane as the customer -> packet -> Claude Code -> free checks -> green
import { readFileSync, existsSync } from 'node:fs';
import { resolve, relative } from 'node:path';
import { execFileSync } from 'node:child_process';
import { parsePolicy, diffPolicies } from '../src/policy.mjs';
import { findSites } from '../src/sites.mjs';

const argv = process.argv.slice(2);
const VALUE_FLAGS = ['--from', '--exclude', '--config', '--recorded', '--recorded-verdict', '--recorded-pack', '--max-attempts'];
const flag = (n) => argv.includes(n);
const opt = (n) => { const i = argv.indexOf(n); return i >= 0 ? argv[i + 1] : undefined; };
const positional = argv.filter((a, i) => !a.startsWith('--') && !VALUE_FLAGS.includes(argv[i - 1]));
const [cmd, policyArg, dirArg] = positional;

const isRevSpec = (p) => /^[^/:]+:.+/.test(p) && !existsSync(p);
function readPolicyArg(p) {
  // "HEAD~1:target/policy.md" reads a committed version through git
  if (isRevSpec(p)) return execFileSync('git', ['show', p], { encoding: 'utf8' });
  return readFileSync(p, 'utf8');
}
function fmt(v, u) {
  if (v == null) return '—';
  return u === 'usd' ? `$${v}` : u === 'days' ? `${v} days` : `${v}%`;
}

if (cmd === 'check') {
  const { check } = await import('../src/check.mjs');
  const r = await check({
    config: opt('--config'), from: opt('--from'), recorded: opt('--recorded'), recordedVerdict: opt('--recorded-verdict'),
    recordedPack: opt('--recorded-pack'), maxAttempts: opt('--max-attempts'), kaneGreen: flag('--kane-green'),
    packetOnly: flag('--packet-only'), noCommit: flag('--no-commit'),
  });
  process.exit(r.status === 'no-change' || r.status === 'green-already' || r.status === 'packet' || r.fixed ? 0 : 1);
}
if (cmd !== 'sites' || !policyArg) {
  console.error('usage: overruled sites <policy.md> [dir] [--from <old-policy.md|REV:path>] [--json] [--source-only] [--residual] [--exclude <path>]');
  process.exit(2);
}

const policyPath = resolve(isRevSpec(policyArg) ? policyArg.split(':').slice(1).join(':') : policyArg);
const root = resolve(dirArg || '.');
const current = readPolicyArg(policyArg);
let numbers;
let diffs = null;
if (opt('--from')) {
  diffs = diffPolicies(readPolicyArg(opt('--from')), current);
  numbers = diffs.filter((d) => d.from != null).map((d) => ({ clause_id: d.clause_id, title: d.title, value: d.from, unit: d.unit }));
} else {
  numbers = parsePolicy(current).flatMap((c) => c.numbers.map((n) => ({ clause_id: c.id, title: c.title, value: n.value, unit: n.unit })));
}
const exclude = [policyPath, ...(opt('--exclude') ? [resolve(opt('--exclude'))] : [])];
let sites = findSites(root, numbers, { exclude });
if (flag('--source-only') || flag('--residual')) sites = sites.filter((s) => s.in_source);

if (flag('--json')) {
  console.log(JSON.stringify({ policy: relative(process.cwd(), policyPath), root: relative(process.cwd(), root) || '.', diffs, numbers, sites }, null, 1));
} else {
  if (diffs) for (const d of diffs) console.log(`${d.clause_id} ${d.title}: ${fmt(d.from, d.unit)} → ${fmt(d.to, d.unit)} (${d.direction})`);
  for (const n of numbers) {
    const hits = sites.filter((s) => s.clause_id === n.clause_id && s.value === n.value && s.unit === n.unit);
    const src = hits.filter((s) => s.in_source).length;
    console.log(`\n${n.clause_id} ${n.title} — ${fmt(n.value, n.unit)}: ${src} in source, ${hits.length - src} in tests/docs/comments`);
    for (const s of hits) console.log(`  ${s.in_source ? '●' : '○'} ${s.file}:${s.line}  [${s.kind}]  ${s.text.slice(0, 100)}`);
  }
  const total = sites.filter((s) => s.in_source).length;
  console.log(`\n${total} in-source line(s) restate ${diffs ? 'a changed' : 'a'} policy number. ● = source, ○ = tests/docs/comments.`);
}
if (flag('--residual') && sites.length) process.exit(1);
// Walk a source tree and list every line that restates a policy number.
import { readdirSync, readFileSync, statSync } from 'node:fs';
import { join, relative, resolve, extname, basename } from 'node:path';
import { patternsFor } from './policy.mjs';

const SKIP_DIRS = new Set(['node_modules', '.git', 'data', 'dist', 'build', 'coverage', '.next', '.context', 'evidence']);
const EXTS = new Set(['.js', '.mjs', '.cjs', '.ts', '.tsx', '.jsx', '.py', '.rb', '.go', '.java', '.html', '.ejs', '.hbs',
  '.vue', '.svelte', '.md', '.json', '.yaml', '.yml', '.sql', '.txt']);

export function walk(root, { exclude = [] } = {}) {
  const files = [];
  const ex = new Set(exclude.map((p) => resolve(p)));
  (function go(d) {
    for (const f of readdirSync(d)) {
      const p = join(d, f);
      if (ex.has(resolve(p))) continue;
      let st;
      try { st = statSync(p); } catch { continue; }
      if (st.isDirectory()) {
        if (!SKIP_DIRS.has(f) && !f.startsWith('.')) go(p);
      } else if (EXTS.has(extname(f)) && !/lock\.json$|\.min\.js$/.test(f) && st.size < 1_000_000) {
        files.push(p);
      }
    }
  })(root);
  return files;
}

const COMMENT_START = ['//', '/*', '*', '--'];

export function classify(file, line) {
  const t = line.trim();
  const isTest = /(^|\/)(tests?|__tests__|spec)\//.test(file) || /\.(test|spec)\.[a-z]+$/.test(file);
  if (isTest) return 'test';
  if (/\.md$/.test(file)) return /readme/i.test(basename(file)) ? 'readme' : 'doc';
  if (COMMENT_START.some((c) => t.startsWith(c)) || (t.startsWith('#') && !t.startsWith('#!'))) return 'comment';
  if (/\bCHECK\s*\(/i.test(t)) return 'db-check';
  if (/description\s*:/.test(t)) return 'tool-schema';
  if (/refus|reason\s*:|throw\s|error/i.test(t)) return 'refusal';
  if (/^-?\s*§\d/.test(t) || /system ?prompt/i.test(t)) return 'prompt';
  if (/\.(html|ejs|hbs|vue|svelte)$/.test(file) || /<\/?(p|span|div|li|h\d|td)\b|class=/.test(t)) return 'page-copy';
  if (/^[\w$.]+\s*[:=]\s*-?\d/.test(t) || /\b(const|let|var)\s+\w+\s*=\s*-?\d/.test(t) || /\b[A-Za-z_$][\w$]*\s*:\s*-?\d/.test(t)) return 'constant';
  return 'code';
}

/** Sites for the given numbers ([{clause_id, title, value, unit}]) under root. */
export function findSites(root, numbers, opts = {}) {
  const files = walk(root, opts);
  const sites = [];
  for (const f of files) {
    const rel = relative(root, f);
    const lines = readFileSync(f, 'utf8').split('\n');
    lines.forEach((line, i) => {
      for (const n of numbers) {
        const p = patternsFor(n);
        const strong = p.strong.some((re) => re.test(line));
        const ctx = !strong && p.contextual && p.contextual.re.test(line) && p.contextual.context.test(line) && !/\.md$/.test(f);
        if (!strong && !ctx) continue;
        const kind = classify(rel, line);
        sites.push({
          clause_id: n.clause_id, value: n.value, unit: n.unit, file: rel, line: i + 1, text: line.trim().slice(0, 160), kind,
          in_source: !['test', 'readme', 'doc', 'comment'].includes(kind), match: strong ? 'literal' : 'contextual',
        });
      }
    });
  }
  return sites;
}
// Read a markdown policy and pull out every number a rule depends on:
// day counts, dollar amounts and percentages, each tied to its clause heading.

const WORDS = ['zero', 'one', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight', 'nine', 'ten', 'eleven', 'twelve',
  'thirteen', 'fourteen', 'fifteen', 'sixteen', 'seventeen', 'eighteen', 'nineteen'];
const TENS = ['', '', 'twenty', 'thirty', 'forty', 'fifty', 'sixty', 'seventy', 'eighty', 'ninety'];
export function numberWord(n) {
  if (n < 20) return WORDS[n];
  if (n < 100) return TENS[Math.floor(n / 10)] + (n % 10 ? `[- ]?${WORDS[n % 10]}` : '');
  return null;
}

/** Clauses: [{ id, title, numbers: [{ value, unit, text }] }]. A clause starts at any markdown heading. */
export function parsePolicy(markdown) {
  const clauses = [];
  let cur = { id: 'preamble', title: '', body: [] };
  for (const line of String(markdown).split('\n')) {
    const h = line.match(/^#{1,6}\s+(.*)$/);
    if (h) {
      clauses.push(cur);
      const sect = h[1].match(/(§\s?\d+[a-z]?)/);
      cur = { id: sect ? sect[1].replace(/\s/g, '') : h[1].trim(), title: h[1].replace(/§\s?\d+[a-z]?\s*/, '').trim(), body: [] };
    } else cur.body.push(line);
  }
  clauses.push(cur);
  const out = [];
  for (const c of clauses) {
    const text = c.body.join('\n').replace(/\*\*/g, '');
    const numbers = [];
    const seen = new Set();
    const add = (value, unit, t) => { const k = `${unit}:${value}`; if (!seen.has(k)) { seen.add(k); numbers.push({ value, unit, text: t }); } };
    for (const m of text.matchAll(/(\d+(?:\.\d+)?)\s*(?:-\s*)?days?\b/gi)) add(Number(m[1]), 'days', m[0]);
    for (const m of text.matchAll(/\$\s?(\d[\d,]*(?:\.\d{2})?)/g)) add(Number(m[1].replace(/,/g, '')), 'usd', m[0]);
    for (const m of text.matchAll(/(\d+(?:\.\d+)?)\s?%/g)) add(Number(m[1]), 'percent', m[0]);
    if (numbers.length || c.id !== 'preamble') out.push({ id: c.id, title: c.title, numbers });
  }
  return out.filter(c => c.numbers.length);
}

/** Clause-level changes between two policy versions (numbers only). */
export function diffPolicies(fromMd, toMd) {
  const a = parsePolicy(fromMd), b = parsePolicy(toMd);
  const byId = new Map(b.map(c => [c.id, c]));
  const diffs = [];
  for (const c of a) {
    const d = byId.get(c.id);
    for (const n of c.numbers) {
      const same = d?.numbers.find(x => x.unit === n.unit && x.value === n.value);
      if (same) continue;
      const repl = d?.numbers.find(x => x.unit === n.unit && !c.numbers.some(y => y.unit === x.unit && y.value === x.value));
      diffs.push({ clause_id: c.id, title: c.title, unit: n.unit, from: n.value, to: repl ? repl.value : null,
        direction: repl == null ? 'removed' : directionOf(c, n, repl) });
    }
  }
  for (const d of b) if (!a.some(c => c.id === d.id)) for (const n of d.numbers) diffs.push({ clause_id: d.id, title: d.title, unit: n.unit, from: null, to: n.value, direction: 'added' });
  return diffs;
}
function directionOf(clause, from, to) {
  // a window or a cap that grows gives the customer more; a threshold that grows asks less of support
  return to.value > from.value ? 'loosen' : 'tighten';
}

/** Regexes that find a number restated in code or copy, including derived forms. */
export function patternsFor({ value, unit }) {
  const v = String(value).replace('.', '\\.');
  const sp = '[-\\s\\u00a0\\u202f]?';
  if (unit === 'days') {
    const w = Number.isInteger(value) ? numberWord(value) : null;
    return {
      strong: [new RegExp(`\\b${v}${sp}days?\\b`, 'i'), new RegExp(`\\b${v}-day\\b`, 'i'), ...(w ? [new RegExp(`\\b${w}${sp}days?\\b`, 'i')] : [])],
      contextual: { re: new RegExp(`(?<![\\w.])${v}(?![\\w.])`), context: /day|window|refund|return/i },
    };
  }
  if (unit === 'usd') {
    const cents = Math.round(value * 100);
    return {
      // a trailing sentence period is fine ("over $200."); "$200.50" or "$2000" is a different number
      strong: [new RegExp(`\\$\\s?${v}(?:\\.00)?(?!\\d|\\.\\d)`), new RegExp(`(?<![\\w.])${cents}(?!\\w|\\.\\d)`)],
      contextual: { re: new RegExp(`(?<![\\w.$])${v}(?:\\.00)?(?!\\w|\\.\\d)`), context: /usd|dollar|amount|credit|max|limit|cap|total|over|price|cents?/i },
    };
  }
  return { strong: [new RegExp(`(?<![\\w.])${v}\\s?%`)], contextual: null };
}

