      const tool = 'escalate_to_human';
      const existing = getEscalationForOrder(db, order.id);
      if (existing || order.status === 'ESCALATED') {
        return {
          ok: false,
          done: false,
          error: 'ALREADY_ESCALATED',
          already_escalated: true,
          order_id: order.id,
