// ---------------------------------------------------------------- history

/** Accept only plain user/assistant text from the client; system and tool turns come from the server alone. */
export function sanitizeHistory(messages) {
  if (!Array.isArray(messages)) throw new ChatInputError('"messages" must be an array of { role, content } objects.');
  const out = [];
  for (const m of messages) {
    if (!m || typeof m !== 'object') continue;
    const role = m.role === 'user' || m.role === 'assistant' ? m.role : null;
    if (!role || typeof m.content !== 'string' || !m.content.trim()) continue;
    out.push({ role, content: m.content.slice(0, 4000) });
  }
  const recent = out.slice(-40);
  if (!recent.length || recent[recent.length - 1].role !== 'user') {
    throw new ChatInputError('"messages" must end with a user message.');
  }
  return recent;
}

// ------------------------------------------------------------------ ollama

function toArgsObject(args) {
  if (args && typeof args === 'object') return args;
  if (typeof args === 'string') {
    try {
      const v = JSON.parse(args);
      return v && typeof v === 'object' ? v : {};
    } catch {
      return {};
    }
  }
  return {};
}

function extractToolCalls(message) {
  if (Array.isArray(message.tool_calls) && message.tool_calls.length) {
    return message.tool_calls
      .map((tc) => ({ name: tc?.function?.name, arguments: toArgsObject(tc?.function?.arguments) }))
      .filter((tc) => tc.name);
  }
  // Some models occasionally print the call as text instead of using the tool channel.
  const calls = [];
  for (const m of String(message.content || '').matchAll(/<tool_call>\s*([\s\S]*?)\s*<\/tool_call>/g)) {
    try {
      const j = JSON.parse(m[1]);
      if (j?.name) calls.push({ name: j.name, arguments: toArgsObject(j.arguments ?? j.parameters) });
    } catch {
      /* ignore malformed */
    }
  }
  return calls;
}

function cleanContent(text) {
  return String(text || '')
    .replace(/<think>[\s\S]*?<\/think>/g, '')
    .replace(/<tool_call>[\s\S]*?<\/tool_call>/g, '')
    .trim();
}

async function callOllama(config, messages, tools, seed, fetchImpl) {
  const body = {
    model: config.model,
    messages,
    tools,
    stream: false,
    options: { temperature: config.temperature, num_ctx: config.numCtx },
  };
  if (seed !== undefined) body.options.seed = seed;
  if (config.think !== undefined) body.think = config.think;

  let res;
  try {
    res = await fetchImpl(config.url, {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify(body),
      signal: AbortSignal.timeout(config.timeoutMs),
    });
  } catch (err) {
    throw new AssistantUnavailableError(`Could not reach Ollama at ${config.url}: ${err.message}`);
  }
  if (!res.ok) {
    const text = await res.text().catch(() => '');
    throw new AssistantUnavailableError(`Ollama returned HTTP ${res.status}: ${text.slice(0, 300)}`);
  }
  const data = await res.json();
  if (data?.error) throw new AssistantUnavailableError(`Ollama error: ${data.error}`);
  return data?.message ?? {};
}

// -------------------------------------------------------------- main loop

export function loadAccountState(db, customerId) {
  return {
    orders: listOrders(db, customerId),
    refunds: listRefunds(db, customerId),
    credits: listCredits(db, customerId),
    escalations: listEscalations(db, customerId),
    balanceCents: creditBalanceCents(db, customerId),
  };
}

function correctionNotice(problems) {
  return [
    '[Automated policy check. This message comes from the store system, not from the customer.]',
    'Your draft reply was NOT sent, because it does not match what actually happened in the store database:',
    ...problems.map((p) => `- ${p.message}`),
    'Policy §6: never say a refund, store credit or escalation has happened or is happening unless an action tool returned "ok": true for it.',
    'Do one of these now: (a) if the customer asked for an action that the policy allows and it has not been done yet, call the tool now; or (b) rewrite your reply so it says plainly what was and was not done.',
    'Answer with only the message for the customer.',
  ].join('\n');
}

/**
 * Run one assistant turn for the signed-in customer.
 * @returns {Promise<{reply:string, actions:object[], tool_calls:object[], verification:object, model:string}>}
 */
export async function runSupportChat({ db, customerId, messages, seed, config = loadConfig(), fetchImpl = fetch }) {
  const customer = getCustomer(db, customerId);
  if (!customer) throw new ChatInputError('Unknown customer.');
  const history = sanitizeHistory(messages);
  const userMessages = history.filter((m) => m.role === 'user').map((m) => m.content);
  // policy.md is read once per request, so the prompt, the tool descriptions and the
  // tool checks all use the same values.
  const policy = loadPolicy();
  if (!policy.ok) console.error(`[policy] unavailable, action tools will refuse: ${policy.error}`);
  const toolbox = createToolbox(db, { customerId, userMessages, policy });
  const tools = toolDefinitions(policy);

  const convo = [{ role: 'system', content: buildSystemPrompt(db, customer, policy) }, ...history];
  const trace = [];
  let corrections = 0;
  let sanitized = false;
  let reply = null;
  const caughtProblems = []; // every mismatch the checker caught, for the response / logs

  for (let call = 0; call < config.maxModelCalls && reply === null; call++) {
    const message = await callOllama(config, convo, seed, fetchImpl);
    const toolCalls = extractToolCalls(message);
    const content = cleanContent(message.content);

    if (toolCalls.length) {
      convo.push({
        role: 'assistant',
        content,
        tool_calls: toolCalls.map((tc) => ({ function: { name: tc.name, arguments: tc.arguments } })),
      });
      for (const tc of toolCalls) {
        const result = toolbox.run(tc.name, tc.arguments);
        trace.push({ name: tc.name, arguments: tc.arguments, result });
        convo.push({ role: 'tool', tool_name: tc.name, content: JSON.stringify(result) });
      }
      continue;
    }

    const verification = content
      ? verifyReply(content, loadAccountState(db, customerId), toolbox.actions)
      : { ok: false, problems: [{ sentence: null, message: 'The reply was empty.' }] };
    caughtProblems.push(...verification.problems.map((p) => p.message));
    if (verification.ok) {
      reply = content;
    } else if (corrections >= config.maxCorrections) {
      reply = sanitizeReply(content, verification, toolbox.actions, toolbox.attempts);
      sanitized = true;
    } else {
      corrections++;
      convo.push({ role: 'assistant', content: content || '(empty)' });
      convo.push({ role: 'user', content: correctionNotice(verification.problems) });
    }
  }

  if (reply === null) {
    // Ran out of model calls (e.g. a tool-call loop): report only what really happened.
    reply = sanitizeReply('', { problems: [] }, toolbox.actions, toolbox.attempts);
    sanitized = true;
  }

  return {
    reply,
    actions: toolbox.actions.map((a) => ({
      type: a.type,
      order_id: a.order_id,
      item: a.item,
      amount: a.amount_cents === null ? null : centsToDollars(a.amount_cents),
      description: describeAction(a),
    })),
    tool_calls: trace,
    verification: { corrections, sanitized, problems: caughtProblems },
    model: config.model,
  };
}

// Express app: pages, dev sign-in, and the chat API.
import path from 'node:path';
import express from 'express';
import cookieParser from 'cookie-parser';
import {
  ROOT_DIR,
  creditBalanceCents,
  getCustomer,
  listCredits,
  listCustomers,
  listOrders,
  listRefunds,
} from './db.js';
import { loadConfig, readPolicy, runSupportChat } from './assistant.js';
import { layout, ledgerPage, messagePage, ordersPage, policyPage, signInPrompt } from './views.js';
import { html } from './util.js';

export const SESSION_COOKIE = 'customer_id';

export function createApp(db, { config = loadConfig(), fetchImpl = fetch } = {}) {
  const app = express();
  app.disable('x-powered-by');
  app.use(cookieParser());
  app.use('/static', express.static(path.join(ROOT_DIR, 'public'), { maxAge: 0 }));

  // Resolve the signed-in customer from the dev cookie on every request.
  app.use((req, _res, next) => {
    req.customer = getCustomer(db, req.cookies?.[SESSION_COOKIE]) ?? null;
    next();
  });

  const page = (res, opts, status = 200) =>
    res.status(status).type('html').send(layout({ ...opts }));

  const requireCustomer = (req, res, next) => {
    if (req.customer) return next();
    return page(
      res,
      { title: 'Sign in', customer: null, body: signInPrompt(listCustomers(db)) },
      401,
    );
  };

  app.get('/', (req, res) => {
    if (req.customer) return res.redirect('/orders');
    return page(res, { title: 'Welcome', customer: null, body: signInPrompt(listCustomers(db)) });
  });

  // Dev-only sign-in: no password, just pick a customer.
  app.get('/login-as/:customerId', (req, res) => {
    const customer = getCustomer(db, req.params.customerId);
    if (!customer) {
      return page(
        res,
        {
          title: 'Unknown customer',
          customer: req.customer,
          body: messagePage('Unknown customer', `There is no customer with id "${req.params.customerId}".`, String(signInPrompt(listCustomers(db)))),
        },
        404,
      );
    }
    res.cookie(SESSION_COOKIE, customer.id, { httpOnly: true, sameSite: 'lax', path: '/' });
    return res.redirect(302, '/orders');
  });

  app.get('/logout', (_req, res) => {
    res.clearCookie(SESSION_COOKIE, { path: '/' });
    res.redirect(302, '/');
  });

  app.get('/orders', requireCustomer, (req, res) => {
    page(res, {
      title: 'Your orders',
      customer: req.customer,
      active: 'orders',
      body: ordersPage(req.customer, listOrders(db, req.customer.id)),
    });
  });

  app.get('/account/ledger', requireCustomer, (req, res) => {
    page(res, {
      title: 'Ledger',
      customer: req.customer,
      active: 'ledger',
      body: ledgerPage(req.customer, {
        refunds: listRefunds(db, req.customer.id),
        credits: listCredits(db, req.customer.id),
        balanceCents: creditBalanceCents(db, req.customer.id),
      }),
    });
  });

  app.get('/policy', (req, res) => {
    page(res, { title: 'Support policy', customer: req.customer, body: policyPage(readPolicy()) });
  });

  app.get('/healthz', (_req, res) => res.json({ ok: true }));

  app.post('/api/chat', express.json({ limit: '256kb' }), async (req, res) => {
    if (!req.customer) {
      return res.status(401).json({ error: 'Not signed in. Visit /login-as/<customerId> first.' });
    }
    const { messages, seed } = req.body ?? {};
    let seedValue;
    if (seed !== undefined && seed !== null && seed !== '') {
      const n = Number(seed);
      if (!Number.isFinite(n)) return res.status(400).json({ error: '"seed" must be a number.' });
      seedValue = Math.trunc(n);
    }
    const started = Date.now();
    const result = await runSupportChat({
      db,
      customerId: req.customer.id,
      messages,
      seed: seedValue,
      config,
      fetchImpl,
    });
    console.log(
      `[chat] ${req.customer.id} seed=${seedValue ?? '-'} tools=[${result.tool_calls
        .map((t) => `${t.name}${t.arguments?.order_id ? `(${t.arguments.order_id})` : ''}:${t.result.ok ? 'ok' : t.result.error}`)
        .join(', ')}] corrections=${result.verification.corrections}${result.verification.sanitized ? ' SANITIZED' : ''} ${Date.now() - started}ms`,
    );
    return res.json({ ...result, message: { role: 'assistant', content: result.reply } });
  });

  app.use((req, res) => {
    if (req.path.startsWith('/api/')) return res.status(404).json({ error: 'Not found.' });
    return page(res, { title: 'Not found', customer: req.customer, body: messagePage('Trail not found', 'That page does not exist.', String(html`<p><a href="/orders">Back to your orders</a></p>`)) }, 404);
  });

  // eslint-disable-next-line no-unused-vars
  app.use((err, req, res, _next) => {
    const status = err.status || err.statusCode || 500;
    if (status >= 500) console.error('[error]', err);
    if (req.path.startsWith('/api/')) {
      const message =
        status === 503
          ? 'The support assistant is unavailable right now (the local model could not be reached). Please try again shortly.'
          : status >= 500
            ? 'Something went wrong on our side. Nothing was changed.'
            : err.expose === false
              ? 'Bad request.'
              : err.message;
      return res.status(status).json({ error: message, detail: status === 503 ? err.message : undefined });
    }
    return page(res, { title: 'Error', customer: req.customer ?? null, body: messagePage('Something went wrong', 'Please try again.') }, status);
  });

  return app;
}

