  return db.prepare('SELECT id, name FROM customers ORDER BY id').all();
}

export function listOrders(db, customerId) {
  return db
    .prepare('SELECT * FROM orders WHERE customer_id = ? ORDER BY delivered_on DESC, id')
    .all(customerId);
}

