  const state = { ...empty, credits: [{ order_id: '1042', amount_cents: 2000 }], balanceCents: 2000 };
  const actions = [{ type: 'store_credit', order_id: '1042', item: 'Alpine Hiking Boots', amount_cents: 2000 }];
  const v = verifyReply("I've added a $25 store credit to your account for order 1042.", state, actions);
  assert.equal(v.ok, false);
});

test('a false balance is a problem', () => {
  const state = { ...empty, credits: [{ order_id: '1042', amount_cents: 2500 }], balanceCents: 2500 };
  const v = verifyReply('Your store credit balance is now $50.00.', state, []);
  assert.equal(v.ok, false);
});

