const lines = POLICY_MD.split('\n');
const openAt = lines.indexOf('```policy-values');
const closeAt = lines.findIndex((l, i) => i > openAt && l === '```');
const editLines = (fn) => {
  const copy = [...lines];
  fn(copy);
  return copy.join('\n');
};
const blockText = lines.slice(openAt, closeAt + 1).join('\n');

const BROKEN = {
